package com.MITProject.TravelerHelperBot.botController;import com.MITProject.TravelerHelperBot.auth.JwtUtil;import com.MITProjectService.bot.Services.DashboardService;import com.MITProjectService.bot.domain.DashBoard;import com.MITProjectService.bot.request.DashBoardRequest;import jakarta.annotation.Resource;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestBody;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;import java.util.Optional;@RestController@RequestMapping("app/dashboard")public class DashBoardController {    @Resource    private DashboardService dashboardService;    @PostMapping("/getDashboard")    public ResponseEntity<DashBoard> getDashboard(@RequestBody DashBoardRequest dashBoardRequest, HttpServletRequest httpServletRequest) {        Long userId = JwtUtil.getUserIdByToken(httpServletRequest.getHeader("Authorization").replace("Bearer ", ""));        dashBoardRequest.setUserId(userId);        Optional<DashBoard> dashBoard = dashboardService.getDashboard(dashBoardRequest);        return ResponseEntity.ok(dashBoard.orElse(null));    }}